window.docContents[198].resolve({"/UD-V___-encapsulation/#Core-C______--UD-V___-encapsulation":{"contents":"Classes with public and private sections, methods, constructors run by new, destructors run by delete, this, single inheritance, subsumption, dispatch by the class tag for virtual methods and namespaces. An abstract data type is a public signature over a private representation, and visibility is a typing rule. Objects are still records of locations with a tag, created by new and never copied, and the destructor runs only on delete. The static class of every receiver and of every delete is written into the tree by the type checker, since  and  carry no types.\n\n\n\n\n\n\n\n\n\n\n\n","context":"Core C++","header":"6. UD V, encapsulation","id":"/UD-V___-encapsulation/#Core-C______--UD-V___-encapsulation"}});